def pre(n):
    return isinstance(n, int) and 0 <= n <= 250

def post(n, result):
    if n <= 2:
        return not result
    def is_prime_helper(d):
        return d * d > n or (n % d != 0 and is_prime_helper(d + 1))
    return is_prime_helper(2) == result

def is_prime_helper(d, n):
    return d * d > n or (n % d != 0 and is_prime_helper(d + 1, n))

# Helper function to compute the correct answer
def is_prime_correct(n):
    if n <= 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True
